public struct FfiConverterTypeWalletDelegate: FfiConverter {
    fileprivate static var handleMap = UniffiHandleMap<WalletDelegate>()

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = WalletDelegate

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> WalletDelegate {
        return WalletDelegateImpl(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: WalletDelegate) -> UnsafeMutableRawPointer {
        guard let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: handleMap.insert(obj: value))) else {
            fatalError("Cast to UnsafeMutableRawPointer failed")
